  function lazyLoading() {
    let lazyLoadAssets = $('[data-lazy-load]');
    // console.log('scrolled');
    lazyLoadAssets.each(function () {
      let myThis = $(this),
        dataLazyLoadSrc = myThis.data('lazy-load-src'),
        dataLazyLoad = myThis.data('lazy-load'),
        assetPosition = myThis.offset().top,
        entireHeight = assetPosition + myThis.outerHeight(),
        scrollPosition = $(window).scrollTop(),
        windowHeight = $(window).height(),
        totalScrollPosition = scrollPosition + windowHeight,
        alreadyLoaded = myThis.hasClass('lazy-loaded');
      if (!alreadyLoaded) {
        if (
          dataLazyLoad == 'img' &&
          totalScrollPosition > assetPosition + 100
        ) {
          $(this).attr('src', dataLazyLoadSrc).addClass('lazy-loaded');
        }
        if (dataLazyLoad == 'bg' && totalScrollPosition > assetPosition - 100) {
          $(this)
            .css('background-image', 'url(' + dataLazyLoadSrc + ')')
            .addClass('lazy-loaded');
        }
      }
    });
  }

