  /* Contact form phone number input field validation to format ###-###-#### */
  // Get the input element for the phone number
  const phoneNumberInput = document.getElementById('phoneNumber');

  // custom function to check if dash, if it is then remove dash
  function checkIfDashAndRemove(characterPosition, element) {
    if (element.charAt(characterPosition) === '-') {
      element =
        element.substring(0, characterPosition) +
        element.substring(characterPosition + 1, element.length);
    }

    return element;
  }

  // custom function to check if dash, if not then add dash
  function checkIfDashAndAdd(characterPosition, element) {
    if (
      element.length > characterPosition &&
      element.charAt(characterPosition) !== '-'
    ) {
      element =
        element.slice(0, characterPosition) +
        '-' +
        element.slice(characterPosition);
    }

    return element;
  }

  // Add an event listener for when the user types in the phone number input field
  if (phoneNumberInput) {
    phoneNumberInput.addEventListener('input', function () {
      // Get the value of the input field
      let phoneNumber = phoneNumberInput.value;

      // invoke checkIfDashAndRemove function for below indexes
      // remove dash unless its for position 3 and 7
      const indicesToExecute = [0, 1, 2, 4, 5, 6, 8, 9, 10, 11];

      for (let i = 0; i < 12; i++) {
        if (indicesToExecute.includes(i)) {
          // Check if the fourth character is a dash, if not add a dash after the third character
          phoneNumber = checkIfDashAndRemove(i, phoneNumber);
        } else {
          // Check if the eighth character is a dash, if not add a dash after the sixth character
          phoneNumber = checkIfDashAndAdd(i, phoneNumber);
        }
      }

      // Remove all non-numeric characters from the input value except for dashes
      phoneNumber = phoneNumber.replace(/[^\d-]/g, '');

      // Limit the input to a maximum of 12 digits
      phoneNumber = phoneNumber.slice(0, 12);

      // Format the phone number as ###-###-####
      const formattedPhoneNumber = phoneNumber.replace(
        /(\d{3})(\d{3})(\d{4})/,
        '$1-$2-$3'
      );

      // Set the value of the input field to the formatted phone number
      phoneNumberInput.value = formattedPhoneNumber;
    });
  }

